<?php get_header(); ?>
<main id="main-content" class="site-main"><div class="site-container content-container content-container--wide search-page">
<header class="archive-header"><p class="section-kicker"><?php esc_html_e( 'Site search', 'job-scam-checker-theme' ); ?></p><h1><?php printf( esc_html__( 'Results for “%s”', 'job-scam-checker-theme' ), esc_html( get_search_query() ) ); ?></h1><?php get_search_form(); ?></header>
<nav class="search-filters" aria-label="<?php esc_attr_e( 'Filter search results', 'job-scam-checker-theme' ); ?>"><?php $jsc_filter = isset( $_GET['content_type'] ) ? sanitize_key( wp_unslash( $_GET['content_type'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification.Recommended ?>
<?php foreach ( array( '' => __( 'All', 'job-scam-checker-theme' ), 'tool' => __( 'Tools', 'job-scam-checker-theme' ), 'scam_article' => __( 'Scam types', 'job-scam-checker-theme' ), 'guide' => __( 'Guides', 'job-scam-checker-theme' ), 'hub' => __( 'Categories', 'job-scam-checker-theme' ) ) as $jsc_type => $jsc_label ) : ?><a <?php echo $jsc_filter === $jsc_type ? 'aria-current="page"' : ''; ?> href="<?php echo esc_url( add_query_arg( array_filter( array( 's' => get_search_query(), 'content_type' => $jsc_type ) ), home_url( '/' ) ) ); ?>"><?php echo esc_html( $jsc_label ); ?></a><?php endforeach; ?></nav>
<?php if ( have_posts() ) : ?><div class="search-results-list"><?php while ( have_posts() ) : the_post(); $jsc_type = get_post_meta( get_the_ID(), '_jsc_content_type', true ); ?><article <?php post_class( 'search-result-card' ); ?>><p class="search-result-card__type"><?php echo esc_html( jsc_theme_content_type_label( $jsc_type ) ); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html( get_the_excerpt() ); ?></p></article><?php endwhile; ?></div><?php the_posts_navigation(); ?>
<?php else : ?><section class="empty-state"><h2><?php esc_html_e( 'No matching pages found', 'job-scam-checker-theme' ); ?></h2><p><?php esc_html_e( 'Try a broader phrase such as “payment”, “recruiter”, “WhatsApp”, or “fake check”. You can also check the message directly.', 'job-scam-checker-theme' ); ?></p><a class="button-link" href="<?php echo esc_url( home_url( '/job-scam-checker/' ) ); ?>"><?php esc_html_e( 'Check a suspicious message', 'job-scam-checker-theme' ); ?></a></section><?php endif; ?>
</div></main><?php get_footer(); ?>
